package com.motionstudio.part2
class RenderGraph<T>{data class Node<T>(val id:String,val dependencies:MutableSet<String>,val execute:(Map<String,T>)->T,var dirty:Boolean=true,var cached:T?=null)
 private val nodes=linkedMapOf<String,Node<T>>();fun add(id:String,deps:Collection<String> = emptyList(),execute:(Map<String,T>)->T){require(id.isNotBlank()&&id !in nodes);nodes[id]=Node(id,deps.toMutableSet(),execute)};fun invalidate(id:String){require(id in nodes);val seen=mutableSetOf<String>();fun rec(x:String){if(seen.add(x)){nodes[x]?.dirty=true;nodes.values.filter{ x in it.dependencies}.forEach{rec(it.id)}}};rec(id)};fun sort():List<String>{val state=mutableMapOf<String,Int>();val out=mutableListOf<String>();fun visit(id:String){when(state[id]){1->error("Render graph cycle at $id");2->return};state[id]=1;val n=nodes[id]?:error("Missing dependency $id");n.dependencies.forEach(::visit);state[id]=2;out+=id};nodes.keys.forEach(::visit);return out};fun execute():Map<String,T>{val result=mutableMapOf<String,T>();for(id in sort()){val n=nodes[id]!!;if(!n.dirty&&n.cached!=null)result[id]=n.cached!! else {val v=n.execute(result);n.cached=v;n.dirty=false;result[id]=v}};return result}}
